+
+function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
+  const limitResult = validateLimit(message.limit);
+  if (!limitResult.valid) return limitResult;
+
+  const beforeResult = validateBefore(message.before);
+  if (!beforeResult.valid) return beforeResult;
+
+  const data: ListSessionsMessage = {type: 'list_sessions'};
+  if (limitResult.limit !== undefined) {
+    data.limit = limitResult.limit;
+  }
+  if (beforeResult.before !== undefined) {
+    data.before = beforeResult.before;
+  }
+
+  return {valid: true, data};
+}
+
+function validateLimit(limit: unknown): {valid: true; limit?: number} | {valid: false; error: string} {
+  if (limit === undefined) {
+    return {valid: true};
+  }
+  if (typeof limit !== 'number' || !Number.isInteger(limit) || limit < 0) {
+    return {valid: false, error: 'limit must be a non-negative integer'};
+  }
+  return {valid: true, limit};
+}
+
+function validateBefore(
+  before: unknown
+): {valid: true; before?: {sessionId: string; updatedAt: string | number}} | {valid: false; error: string} {
+  if (before === undefined) {
+    return {valid: true};
+  }
+  if (typeof before !== 'object' || before === null || Array.isArray(before)) {
+    return {valid: false, error: 'before must be an object'};
+  }
+  const cursor = before as Record<string, unknown>;
+  if (typeof cursor.sessionId !== 'string' || cursor.sessionId.length < 1 || cursor.sessionId.length > 128) {
+    return {valid: false, error: 'before.sessionId must be a string between 1 and 128 characters'};
+  }
+  if (
+    (typeof cursor.updatedAt !== 'string' && typeof cursor.updatedAt !== 'number') ||
+    !Number.isFinite(new Date(cursor.updatedAt).getTime())
+  ) {
+    return {valid: false, error: 'before.updatedAt must be a valid date or timestamp'};
+  }
+  return {
+    valid: true,
+    before: {
+      sessionId: cursor.sessionId,
+      updatedAt: cursor.updatedAt,
+    },
+  };
+}
